class Zipper:
    def __init__(self, node, crumbs):
        # node is a tuple: (value, left, right)
        # crumbs is a list of breadcrumbs; each breadcrumb is a tuple:
        # ('left', parent_value, right_subtree)  -- we moved into left child
        # ('right', parent_value, left_subtree)  -- we moved into right child
        self.node = node
        self.crumbs = crumbs

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, [])

    def value(self):
        return self.node[0]

    def set_value(self, value):
        _, left, right = self.node
        new_node = (value, left, right)
        return Zipper(new_node, list(self.crumbs))

    def left(self):
        left_sub = self.node[1]
        if left_sub is None:
            return None
        # store parent value and right subtree in crumb
        parent_value = self.node[0]
        right_sub = self.node[2]
        new_crumbs = list(self.crumbs)
        new_crumbs.append(('left', parent_value, right_sub))
        return Zipper(left_sub, new_crumbs)

    def set_left(self, tree):
        value, _, right = self.node
        new_node = (value, tree, right)
        return Zipper(new_node, list(self.crumbs))

    def right(self):
        right_sub = self.node[2]
        if right_sub is None:
            return None
        parent_value = self.node[0]
        left_sub = self.node[1]
        new_crumbs = list(self.crumbs)
        new_crumbs.append(('right', parent_value, left_sub))
        return Zipper(right_sub, new_crumbs)

    def set_right(self, tree):
        value, left, _ = self.node
        new_node = (value, left, tree)
        return Zipper(new_node, list(self.crumbs))

    def up(self):
        if not self.crumbs:
            return None
        last = self.crumbs[-1]
        rest = list(self.crumbs[:-1])
        kind = last[0]
        parent_value = last[1]
        other = last[2]
        if kind == 'left':
            # we came up from left child; other is right subtree
            new_node = (parent_value, self.node, other)
        else:  # 'right'
            # came up from right child; other is left subtree
            new_node = (parent_value, other, self.node)
        return Zipper(new_node, rest)

    def to_tree(self):
        z = self
        while True:
            upz = z.up()
            if upz is None:
                return z.node
            z = upz
